   625  mpz_init_set_str(mrb_state *mrb, mpz_t *x, const char *s, mrb_int len, mrb_int base)
   626  {
   627    int retval = 0;
   628    mpz_t t,m,bb;
   629    short sn;
   630    unsigned int k;
   631    mpz_init(mrb,x);
   632    mpz_init_set_int(mrb,&m,1);
   633    mpz_init(mrb,&t);
   634    zero(x);
   635    if (*s == '-') {
   636      sn = -1; s++;
   637    }
   638    else if (base < 0) {          /* trick: negative if base < 0 */
   639      sn = -1; base = -base;
   640    }
   641    else
   642      sn = 1;
   643    mpz_init_set_int(mrb,&bb, base);
   644    for (mrb_int i = len-1; i>=0; i--) {
   645      if (s[i]=='_') continue;
   646      if (s[i] >= '0' && s[i] <= '9')
   647        k = (unsigned int)s[i] - (unsigned int)'0';
   648      else if (s[i] >= 'A' && s[i] <= 'Z')
   649        k = (unsigned int)s[i] - (unsigned int)'A'+10;
   650      else if (s[i] >= 'a' && s[i] <= 'z')
   651        k = (unsigned int)s[i] - (unsigned int)'a'+10;
   652      else {
   653        retval = (-1);
   654        break;
   655      }
   656      if (k >= base) {
   657        retval = (-1);
   658        break;
   659      }
   660      mpz_mul_int(mrb,&t,&m,(mrb_int)k);
   661      mpz_add(mrb,x,x,&t);
   662      mpz_mul(mrb,&m,&m,&bb);
   663    }
   664    if (x->sn)
   665      x->sn = sn;
   666    mpz_clear(mrb,&m);
   667    mpz_clear(mrb,&bb);
   668    mpz_clear(mrb,&t);
   669    return retval;
   670  }
